// SportsPress -> venues, courts, leagues, seasons, teams, season_teams, match_days, matches, match_results,
// ladder_adjustments. Pure mapping over the fetched JSON; SQL is generated by the caller.

import type { LeagueCode, MatchDayKind, MatchStatus } from '../../src/server/db/schema/enums'
import type { SeasonSettings } from '../../src/server/db/schema/competition'
import {
  asStandings,
  compareLadders,
  computeLadder,
  outcomeTable,
  tableRow,
  type LadderDiff,
  type LadderGame,
  type OutcomeGame,
} from '../../src/lib/wp-import/ladder'
import { mapEventResult, type MappedResult } from '../../src/lib/wp-import/results'
import { leagueSlug, parseSeasonName, seasonName, seasonSlug } from '../../src/lib/wp-import/routes'
import type { SqlValue } from '../../src/lib/wp-import/sql'
import { decodeEntities, nameKey } from '../../src/lib/wp-import/text'
import { parseEventTitle, type SideText } from '../../src/lib/wp-import/titles'
import { stableId } from './ids'
import type { SpEvent, WpData } from './types'

type Row = Record<string, SqlValue>

export const RECONCILIATION_REASON = 'wp-import reconciliation'

// ── Static reference data ────────────────────────────────────────────────────

export const VENUES = [
  {
    key: 'robyn-webster',
    name: 'Robyn Webster Sports Centre',
    slug: 'robyn-webster-sports-centre',
    address: 'Holbeach Ave, Tempe NSW 2044',
    query: 'Robyn Webster Sports Centre, Holbeach Ave, Tempe NSW',
  },
  {
    key: 'mlc',
    name: 'MLC School',
    slug: 'mlc-school',
    address: 'Rowley St, Burwood NSW 2134',
    query: 'MLC School, Rowley St, Burwood NSW',
  },
  {
    key: 'five-dock',
    name: 'Five Dock Leisure Centre',
    slug: 'five-dock-leisure-centre',
    address: 'William St, Five Dock NSW 2046',
    query: 'Five Dock Leisure Centre, William St, Five Dock NSW',
  },
] as const

type VenueKey = (typeof VENUES)[number]['key']

/** SportsPress "venues" are courts. Court 1–3 are at Robyn Webster (Tempe); "MLC" is the MLC School court. */
const COURT_VENUE = (name: string): VenueKey | null => (/^court \d+$/i.test(name) ? 'robyn-webster' : /^mlc$/i.test(name) ? 'mlc' : null)

const LEAGUES: Record<
  LeagueCode,
  { name: string; weekday: number; venue: VenueKey; format: 'social' | 'super'; sort: number; spSlug: string }
> = {
  TNL: { name: 'Thursday Night League', weekday: 4, venue: 'robyn-webster', format: 'social', sort: 0, spSlug: 'a-league' },
  FNL: { name: 'Friday Night League', weekday: 5, venue: 'robyn-webster', format: 'social', sort: 1, spSlug: 'fnl' },
  SNL: { name: 'Saturday Night League', weekday: 6, venue: 'robyn-webster', format: 'social', sort: 2, spSlug: 'snl' },
  SAL: { name: 'Sunday Afternoon League', weekday: 0, venue: 'mlc', format: 'social', sort: 3, spSlug: 'sal' },
  TVSL: { name: 'Tempe Volleyball Super League', weekday: 0, venue: 'robyn-webster', format: 'super', sort: 4, spSlug: 'ssl' },
}

/** Team names typed into finals titles that don't match the team record. */
const TEAM_ALIASES: Record<string, string> = { benchies: 'benchwarmers', super6: 'supersix' }

// ── Output ───────────────────────────────────────────────────────────────────

export type SeasonInfo = { id: string; wpId: number; code: LeagueCode; slug: string; leagueSlug: string; name: string; lastDate: string }

export type Competition = {
  venues: Row[]
  courts: Row[]
  leagues: Row[]
  teams: Row[]
  seasons: Row[]
  seasonTeams: Row[]
  matchDays: Row[]
  matches: Row[]
  matchResults: Row[]
  ladderAdjustments: Row[]
  /** By SportsPress season term id. */
  seasonsByWp: Map<number, SeasonInfo>
  leagueIdByCode: Map<LeagueCode, string>
  leagueCodeByWp: Map<number, LeagueCode>
  /** Latest season each team played in (by SportsPress team id). */
  teamLastSeason: Map<number, SeasonInfo>
  report: CompetitionReport
}

export type CompetitionReport = {
  unmappedLeagues: string[]
  unmappedSeasons: string[]
  unmappedCourts: string[]
  skippedEvents: string[]
  byeEvents: number
  skipDays: number
  unresolvedNames: string[]
  setScoresDropped: number
  forfeits: number
  ladders: {
    season: string
    table: string
    outcomeModelAgrees: boolean | null
    diffs: (LadderDiff & { team: string })[]
    withFinalsMatches: boolean
    adjustments: number
  }[]
  seasonsWithoutTable: string[]
}

const iso = (gmt: string) => `${gmt.replace(' ', 'T')}${gmt.includes('.') ? '' : '.000'}Z`

export const venueId = (key: string) => stableId('venue', key)

export function buildCompetition(data: WpData): Competition {
  const report: CompetitionReport = {
    unmappedLeagues: [],
    unmappedSeasons: [],
    unmappedCourts: [],
    skippedEvents: [],
    byeEvents: 0,
    skipDays: 0,
    unresolvedNames: [],
    setScoresDropped: 0,
    forfeits: 0,
    ladders: [],
    seasonsWithoutTable: [],
  }

  const venues: Row[] = VENUES.map((v, i) => ({
    id: venueId(v.key),
    name: v.name,
    slug: v.slug,
    address: v.address,
    map_url: `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(v.query)}`,
    sort: i,
  }))

  // Courts
  const courtById = new Map<number, { id: string; sort: number; name: string }>()
  const courts: Row[] = []
  for (const [i, v] of [...data.venues].sort((a, b) => a.name.localeCompare(b.name)).entries()) {
    const key = COURT_VENUE(v.name)
    if (!key) {
      report.unmappedCourts.push(`${v.name} (${v.id})`)
      continue
    }
    const id = stableId('court', v.id)
    courtById.set(v.id, { id, sort: i, name: v.name })
    courts.push({ id, venue_id: venueId(key), name: v.name, sort: i, wp_id: v.id })
  }

  // Leagues
  const leagueIdByCode = new Map<LeagueCode, string>()
  const leagueCodeByWp = new Map<number, LeagueCode>()
  const leagues: Row[] = []
  for (const [code, l] of Object.entries(LEAGUES) as [LeagueCode, (typeof LEAGUES)[LeagueCode]][]) {
    const sp = data.leagues.find((t) => t.slug === l.spSlug)
    const id = stableId('league', code)
    leagueIdByCode.set(code, id)
    if (sp) leagueCodeByWp.set(sp.id, code)
    leagues.push({
      id,
      code,
      name: l.name,
      slug: leagueSlug(code),
      weekday: l.weekday,
      default_venue_id: venueId(l.venue),
      format: l.format,
      sort: l.sort,
      active: true,
      wp_id: sp?.id ?? null,
    })
  }
  for (const t of data.leagues)
    if (!leagueCodeByWp.has(t.id)) report.unmappedLeagues.push(`${t.name} (${t.slug}, id ${t.id}, ${t.count} items)`)

  // Teams
  const teamIdByWp = new Map<number, string>()
  const teamName = new Map<number, string>()
  const teamByKey = new Map<string, number>()
  const teams: Row[] = data.teams.map((t) => {
    const id = stableId('team', t.id)
    const name = decodeEntities(t.title.rendered).trim()
    teamIdByWp.set(t.id, id)
    teamName.set(t.id, name)
    teamByKey.set(nameKey(name), t.id)
    return { id, name, slug: t.slug, wp_id: t.id }
  })

  // Seasons (rows built after their events are grouped)
  type SeasonDraft = { info: SeasonInfo; quarter: number; year: number; events: SpEvent[] }
  const seasonDrafts = new Map<number, SeasonDraft>()
  for (const s of data.seasons) {
    const p = parseSeasonName(s.name)
    if (!p) {
      report.unmappedSeasons.push(`${s.name} (${s.id})`)
      continue
    }
    seasonDrafts.set(s.id, {
      info: {
        id: stableId('season', s.id),
        wpId: s.id,
        code: p.code,
        slug: seasonSlug(p.code, p.quarter, p.year),
        leagueSlug: leagueSlug(p.code),
        name: seasonName(p.code, p.quarter, p.year),
        lastDate: '',
      },
      quarter: p.quarter,
      year: p.year,
      events: [],
    })
  }
  for (const e of data.events) {
    const d = seasonDrafts.get(e.seasons[0] ?? -1)
    if (!d) {
      report.skippedEvents.push(`${e.id} ${e.slug}: no mapped season`)
      continue
    }
    const lc = leagueCodeByWp.get(e.leagues[0] ?? -1)
    if (lc && lc !== d.info.code) report.skippedEvents.push(`${e.id}: league ${lc} differs from season ${d.info.name} (kept in season)`)
    d.events.push(e)
  }

  const seasons: Row[] = []
  const seasonTeams: Row[] = []
  const matchDays: Row[] = []
  const matches: Row[] = []
  const matchResults: Row[] = []
  const ladderAdjustments: Row[] = []
  const seasonsByWp = new Map<number, SeasonInfo>()
  const teamLastSeason = new Map<number, SeasonInfo>()
  const latestByLeague = new Map<LeagueCode, SeasonDraft>()

  for (const d of seasonDrafts.values()) {
    if (d.events.length === 0) continue
    const dates = d.events.map((e) => e.date.slice(0, 10)).sort()
    d.info.lastDate = dates.at(-1)!
    const prev = latestByLeague.get(d.info.code)
    if (!prev || prev.info.lastDate < d.info.lastDate) latestByLeague.set(d.info.code, d)
  }

  for (const d of seasonDrafts.values()) {
    if (d.events.length === 0) {
      report.unmappedSeasons.push(`${d.info.name}: no events`)
      continue
    }
    const { info } = d
    seasonsByWp.set(info.wpId, info)
    const superLeague = LEAGUES[info.code].format === 'super'
    const inSeason = new Set<number>()
    const seasonTeamKeys = new Map<string, number>()

    // Teams known to this season, for resolving names typed in finals titles.
    for (const e of d.events) for (const t of e.teams) if (t > 0) inSeason.add(t)
    for (const t of inSeason) seasonTeamKeys.set(nameKey(teamName.get(t) ?? ''), t)
    // Names as typed in this season's regular-match titles, whose team ids are known ("SWEATY PENGUINS" was the
    // PENGUINS team that season).
    for (const e of d.events) {
      const p = parseEventTitle(e.title.rendered)
      if (p.kind !== 'match' || p.stageTitle) continue
      const [h, a] = e.teams
      if (p.home.team && h && h > 0 && !seasonTeamKeys.has(nameKey(p.home.team))) seasonTeamKeys.set(nameKey(p.home.team), h)
      if (p.away.team && a && a > 0 && !seasonTeamKeys.has(nameKey(p.away.team))) seasonTeamKeys.set(nameKey(p.away.team), a)
    }

    const resolveName = (name: string): number | null => {
      const k = nameKey(name)
      const key = TEAM_ALIASES[k] ?? k
      return seasonTeamKeys.get(key) ?? teamByKey.get(key) ?? null
    }

    type M = {
      e: SpEvent
      date: string
      time: string
      stage: string | null
      home: { team: number | null; label: string | null }
      away: { team: number | null; label: string | null }
      duty: { team: number | null; label: string | null }
      result: MappedResult | null
      court: { id: string; sort: number } | null
    }
    const ms: M[] = []
    const dayNotes = new Map<string, string[]>()
    const addNote = (date: string, note: string) => {
      const list = dayNotes.get(date) ?? []
      if (!list.includes(note)) list.push(note)
      dayNotes.set(date, list)
    }
    const skipDates = new Set<string>()

    const side = (s: SideText | null, wpTeam: number | undefined, e: SpEvent): { team: number | null; label: string | null } => {
      if (wpTeam && wpTeam > 0 && teamIdByWp.has(wpTeam)) return { team: wpTeam, label: null }
      if (!s) return { team: null, label: null }
      if (s.team) {
        const t = resolveName(s.team)
        if (t) {
          inSeason.add(t)
          return { team: t, label: null }
        }
        report.unresolvedNames.push(`${info.name} ${e.slug}: "${s.team}"`)
        return { team: null, label: s.label ?? s.team }
      }
      return { team: null, label: s.label ?? null }
    }

    for (const e of d.events) {
      const date = e.date.slice(0, 10)
      const parsed = parseEventTitle(e.title.rendered)
      if (parsed.kind === 'bye') {
        report.byeEvents++
        for (const t of e.teams) if (t > 0) inSeason.add(t)
        for (const n of parsed.teams) {
          const t = resolveName(n)
          if (t) inSeason.add(t)
        }
        continue
      }
      if (parsed.kind === 'skip') {
        skipDates.add(date)
        addNote(date, parsed.note)
        continue
      }
      const [h, a] = e.teams
      const home = side(parsed.home, h, e)
      const away = side(parsed.away, a, e)
      const duty = side(parsed.duty, undefined, e)
      for (const n of parsed.notes) addNote(date, n)
      if (parsed.duty?.note) addNote(date, parsed.duty.note)
      const result = h && a && h > 0 && a > 0 ? mapEventResult(e.results, h, a) : null
      if (result?.setScoresDropped) report.setScoresDropped++
      if (result?.forfeit) report.forfeits++
      const court = e.venues[0] !== undefined ? (courtById.get(e.venues[0]) ?? null) : null
      ms.push({ e, date, time: e.date.slice(11, 16), stage: parsed.stageTitle, home, away, duty, result, court })
    }

    // Sessions are the season's distinct start times; positions order the courts within a session.
    const sessions = [...new Set(ms.map((m) => m.time))].sort()
    const gaps = sessions.slice(1).map((t, i) => minutes(t) - minutes(sessions[i]!))
    const sessionMinutes = superLeague ? 90 : gaps.length ? Math.min(...gaps.filter((g) => g > 0), 60) : 60

    const byDay = new Map<string, M[]>()
    for (const m of ms) byDay.set(m.date, [...(byDay.get(m.date) ?? []), m])
    const allDates = [...new Set([...byDay.keys(), ...skipDates])].sort()

    const slot = new Map<M, { session: number; position: number }>()
    for (const list of byDay.values()) {
      for (const [si, time] of sessions.entries()) {
        list
          .filter((m) => m.time === time)
          .sort((x, y) => (x.court?.sort ?? 99) - (y.court?.sort ?? 99) || x.e.id - y.e.id)
          .forEach((m, position) => slot.set(m, { session: si, position }))
      }
    }
    // Default court per slot position: the court most used there.
    const positions = Math.max(0, ...[...slot.values()].map((s) => s.position + 1))
    const defaultCourtIds: string[] = []
    const fallback = mostCommon(ms.map((m) => m.court?.id).filter((x): x is string => !!x)) ?? ''
    for (let p = 0; p < positions; p++) {
      const used = ms.filter((m) => slot.get(m)!.position === p && m.court).map((m) => m.court!.id)
      defaultCourtIds.push(mostCommon(used) ?? fallback)
    }

    // Match days
    let number = 0
    const dayIds = new Map<string, string>()
    let firstDate = ''
    for (const date of allDates) {
      const list = byDay.get(date) ?? []
      const kind: MatchDayKind = list.length
        ? list.some((m) => m.stage === 'Grand Final' || m.stage === '3rd Place')
          ? 'final'
          : list.some((m) => m.stage)
            ? 'semi'
            : 'regular'
        : 'skip'
      if (kind === 'skip') report.skipDays++
      if (!firstDate) firstDate = date
      const id = stableId('match-day', `${info.wpId}:${date}`)
      dayIds.set(date, id)
      const overrides: Record<string, string> = {}
      for (const m of list) {
        const s = slot.get(m)!
        if (m.court && m.court.id !== defaultCourtIds[s.position]) overrides[`${s.session}:${s.position}`] = m.court.id
      }
      const published = list.filter((m) => m.result).map((m) => m.e.modified_gmt)
      matchDays.push({
        id,
        season_id: info.id,
        date,
        kind,
        number: kind === 'skip' ? 0 : ++number,
        note: dayNotes.get(date)?.join('; ') ?? null,
        court_overrides: overrides,
        results_published_at: published.length ? iso(published.sort().at(-1)!) : null,
      })
    }

    // Matches and results
    const ladderGames: LadderGame[] = []
    const ladderGamesWithFinals: LadderGame[] = []
    const outcomeGames: OutcomeGame[] = []
    for (const m of ms) {
      const s = slot.get(m)!
      const id = stableId('event', m.e.id)
      const status: MatchStatus = m.result ? (m.result.forfeit ? 'forfeit' : 'played') : 'scheduled'
      const ref = (x: { team: number | null; label: string | null }) =>
        [x.team ? teamIdByWp.get(x.team)! : null, x.team ? null : x.label] as const
      const [ht, hl] = ref(m.home)
      const [at, al] = ref(m.away)
      const [dt, dl] = superLeague ? [null, null] : ref(m.duty)
      matches.push({
        id,
        season_id: info.id,
        match_day_id: dayIds.get(m.date)!,
        session: s.session,
        position: s.position,
        start_time: m.time,
        court_id: m.court?.id ?? null,
        home_team_id: ht,
        home_label: hl ?? (ht ? null : 'TBC'),
        away_team_id: at,
        away_label: al ?? (at ? null : 'TBC'),
        duty_team_id: dt,
        duty_label: dl,
        stage_title: m.stage,
        status,
        slug: m.e.slug,
        wp_id: m.e.id,
      })
      if (m.result) {
        for (const kind of ['published', 'draft'] as const) {
          matchResults.push({
            match_id: id,
            kind,
            home_sets: m.result.homeSets,
            away_sets: m.result.awaySets,
            set_scores: m.result.setScores,
            home_points: m.result.homePoints,
            away_points: m.result.awayPoints,
          })
        }
      }
      const g: LadderGame = { date: m.date, regular: !m.stage, homeTeam: ht, awayTeam: at, result: m.result }
      ladderGames.push(g)
      ladderGamesWithFinals.push({ ...g, regular: true })
      const oc = (m.e as SpEvent & { outcome?: unknown }).outcome
      const outcomeOf = (t: number | null) =>
        t && oc && typeof oc === 'object' && !Array.isArray(oc)
          ? (((oc as Record<string, unknown>)[String(t)] as string | undefined) ?? null)
          : null
      outcomeGames.push({ ...g, homeOutcome: outcomeOf(m.home.team), awayOutcome: outcomeOf(m.away.team) })
    }

    // Season teams
    const members = [...inSeason].filter((t) => teamIdByWp.has(t))
    const tables = data.tables.filter((t) => t.seasons.includes(info.wpId))
    for (const t of tables)
      for (const k of Object.keys(t.data))
        if (Number(k) > 0 && teamIdByWp.has(Number(k)) && !members.includes(Number(k))) members.push(Number(k))
    members.sort((x, y) => (teamName.get(x) ?? '').localeCompare(teamName.get(y) ?? ''))
    members.forEach((t, sort) => seasonTeams.push({ season_id: info.id, team_id: teamIdByWp.get(t)!, sort }))
    for (const t of members) {
      const prev = teamLastSeason.get(t)
      if (!prev || prev.lastDate < info.lastDate) teamLastSeason.set(t, info)
    }

    // Ladder reconciliation against the SportsPress table(s) for this season.
    const fixtureTeams = members.map((t) => ({ id: teamIdByWp.get(t)!, name: teamName.get(t) ?? '' }))
    const nameOf = new Map(fixtureTeams.map((t) => [t.id, t.name]))
    // SportsPress tables only keep their latest season; older seasons are compared with the table SportsPress would
    // have shown, rebuilt from the events' outcomes (checked against the real tables in the report).
    const table = tables.sort((x, y) => y.id - x.id)[0]
    const rebuilt = outcomeTable(
      fixtureTeams.map((t) => t.id),
      outcomeGames,
    )
    const rows = table
      ? Object.entries(table.data)
          .filter(([k]) => Number(k) > 0 && teamIdByWp.has(Number(k)))
          .map(([k, v]) => tableRow(teamIdByWp.get(Number(k))!, v))
      : rebuilt.filter((r) => r.p > 0)
    const outcomeModelAgrees = table ? compareLadders(asStandings(rebuilt), rows).length === 0 : null
    if (!table) report.seasonsWithoutTable.push(info.name)
    if (rows.length) {
      const diffs = compareLadders(computeLadder(fixtureTeams, ladderGames), rows)
      const withFinals = compareLadders(computeLadder(fixtureTeams, ladderGamesWithFinals), rows)
      const finalsExplain = diffs.length > 0 && withFinals.length === 0
      let adjustments = 0
      if (!finalsExplain) {
        for (const diff of diffs) {
          if (diff.pointsDiff === 0) continue
          adjustments++
          ladderAdjustments.push({
            id: stableId('ladder-adjustment', `${info.wpId}:${diff.teamId}`),
            season_id: info.id,
            team_id: diff.teamId,
            points: diff.pointsDiff,
            reason: RECONCILIATION_REASON,
          })
        }
      }
      report.ladders.push({
        season: info.name,
        table: table ? `${decodeEntities(table.title.rendered)} (${table.slug})` : 'table rebuilt from SportsPress outcomes',
        outcomeModelAgrees,
        diffs: diffs.map((x) => ({ ...x, team: nameOf.get(x.teamId) ?? x.teamId })),
        withFinalsMatches: finalsExplain,
        adjustments,
      })
    }

    const settings: SeasonSettings = {
      sessions,
      sessionMinutes,
      meetings: meetingsOf(ms.filter((m) => !m.stage)),
      includeFinals: ms.some((m) => m.stage),
      seed: 0,
      skipDates: [...skipDates].sort().map((date) => ({ date, reason: dayNotes.get(date)?.join('; ') ?? 'No games' })),
      defaultCourtIds,
    }
    const latest = latestByLeague.get(info.code) === d
    const firstGmt = d.events.map((e) => e.date_gmt).sort()[0]!
    seasons.push({
      id: info.id,
      league_id: leagueIdByCode.get(info.code)!,
      name: info.name,
      slug: info.slug,
      year: d.year,
      quarter: d.quarter,
      start_date: firstDate,
      status: latest ? 'published' : 'archived',
      settings,
      points_win: 3,
      points_draw: 2,
      points_loss: 1,
      sets_per_match: superLeague ? 5 : 2,
      duty_enabled: !superLeague,
      generated_from: null,
      edited: true,
      published_at: iso(firstGmt),
      wp_id: info.wpId,
    })
  }

  return {
    venues,
    courts,
    leagues,
    teams,
    seasons,
    seasonTeams,
    matchDays,
    matches,
    matchResults,
    ladderAdjustments,
    seasonsByWp,
    leagueIdByCode,
    leagueCodeByWp,
    teamLastSeason,
    report,
  }
}

const minutes = (hhmm: string) => Number(hhmm.slice(0, 2)) * 60 + Number(hhmm.slice(3, 5))

function mostCommon<T>(xs: T[]): T | null {
  const counts = new Map<T, number>()
  for (const x of xs) counts.set(x, (counts.get(x) ?? 0) + 1)
  let best: T | null = null
  let n = 0
  for (const [x, c] of counts) if (c > n) [best, n] = [x, c]
  return best
}

/** Times each pair met in the round robin (the most common count). */
function meetingsOf(ms: { home: { team: number | null }; away: { team: number | null } }[]): number {
  const pairs = new Map<string, number>()
  for (const m of ms) {
    if (!m.home.team || !m.away.team) continue
    const k = [m.home.team, m.away.team].sort((a, b) => a - b).join(':')
    pairs.set(k, (pairs.get(k) ?? 0) + 1)
  }
  return mostCommon([...pairs.values()]) ?? 1
}
